package com.keremhub.app;

import com.sun.net.httpserver.HttpServer;
import java.io.*;
import java.net.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Real HTTP range contract tests, with generated bytes instead of a large video fixture. */
public final class RangeMediaSourceTest {
    private static final long SIZE = 3L * 1024 * 1024 * 1024 + 123;
    private static final AtomicInteger requests = new AtomicInteger();
    private static void check(boolean ok, String message) { if (!ok) throw new AssertionError(message); }
    private static void verify(RangeMediaSource source,long position,int count) throws Exception {
        byte[] data=new byte[count+5];
        int length=source.readAt(position,data,3,count);
        check(length>0&&length<=count,"Read size");
        for(int i=0;i<length;i++) check(data[i+3]==(byte)((position+i)%251),"Incorrect data at "+(position+i));
        check(data[0]==0&&data[length+3]==0,"Buffer bounds");
    }
    public static void main(String[] args) throws Exception {
        HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
        server.createContext("/video", exchange->{
            requests.incrementAndGet();
            String[] range=exchange.getRequestHeaders().getFirst("Range").substring(6).split("-");
            long from=Long.parseLong(range[0]),to=Math.min(SIZE-1,Long.parseLong(range[1]));
            byte[] bytes=new byte[(int)(to-from+1)];
            for(int i=0;i<bytes.length;i++) bytes[i]=(byte)((from+i)%251);
            exchange.getResponseHeaders().set("Content-Range","bytes "+from+"-"+to+"/"+SIZE);
            exchange.sendResponseHeaders(206,bytes.length);
            try(OutputStream out=exchange.getResponseBody()){out.write(bytes);}
        });
        server.createContext("/no-range", exchange->{exchange.sendResponseHeaders(200,1);exchange.getResponseBody().write(0);exchange.close();});
        server.createContext("/truncated", exchange->{exchange.getResponseHeaders().set("Content-Range","bytes 0-262143/"+SIZE);exchange.sendResponseHeaders(206,1);exchange.getResponseBody().write(0);exchange.close();});
        server.start();
        try {
            String base="http://127.0.0.1:"+server.getAddress().getPort();
            try(RangeMediaSource source=new RangeMediaSource(base+"/video")){
                check(source.getSize()==SIZE,"64-bit file size");
                verify(source,0,1000); verify(source,100,500);
                check(requests.get()==1,"Repeated reads should use cache");
                verify(source,262140,100); // A short read across a block boundary is legal.
                verify(source,262144,100);
                verify(source,SIZE-123,123); // MP4 metadata near EOF, above the 2 GB boundary.
                check(source.readAt(SIZE,new byte[1],0,1)==-1,"EOF");
                check(source.readAt(0,new byte[0],0,0)==0,"Zero-byte read");
                int before=requests.get();
                for(int i=1;i<=10;i++) verify(source,(long)i*262144,100);
                verify(source,0,100);
                check(requests.get()>before+9,"Old cache blocks should be evicted");
                source.close();
                try{source.readAt(0,new byte[1],0,1);throw new AssertionError("Closed stream accepted read");}catch(IOException expected){}
            }
            for(String path:new String[]{"/no-range","/truncated"}){
                try(RangeMediaSource ignored=new RangeMediaSource(base+path)){throw new AssertionError("Invalid server accepted: "+path);}catch(IOException expected){}
            }
            System.out.println("PASS: range reads, cache reuse/eviction, >2GB tail seeks, EOF, close, invalid/truncated responses");
            if(args.length>0)try(RangeMediaSource live=new RangeMediaSource(args[0])){
                long start=System.nanoTime();byte[] data=new byte[1024];
                check(live.readAt(live.getSize()-1024,data,0,1024)>0,"Live tail seek");
                System.out.println("PASS: live video range + tail seek ("+live.getSize()+" bytes, tail "+((System.nanoTime()-start)/1000000)+" ms)");
            }
        } finally { server.stop(0); }
    }
}
